3	const pendingSaves = new Map<string, ReturnType<typeof window.setTimeout>>();
4	const STRUCTURED_CACHE_ENTRY_KIND = "memos.editor-cache";
5	const STRUCTURED_CACHE_ENTRY_VERSION = 1;
6	
7	function deserializeContent(raw: string): string {
8	  try {
9	    const parsed = JSON.parse(raw) as { kind?: unknown; version?: unknown; content?: unknown };
10	    if (
11	      parsed.kind === STRUCTURED_CACHE_ENTRY_KIND &&
12	      parsed.version === STRUCTURED_CACHE_ENTRY_VERSION &&
13	      typeof parsed.content === "string"
14	    ) {
15	      return parsed.content;
16	    }
17	  } catch {
18	    // Drafts have historically been stored as raw markdown strings.
19	  }
20	
21	  return raw;
22	}
23	
24	function writeEntry(key: string, content: string): void {
25	  if (content.trim()) {
26	    localStorage.setItem(key, content);
27	  } else {
28	    localStorage.removeItem(key);
29	  }
30	}
